sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '' || newValue == oldValue) {
      return;
   }
   //Type appropriate comment here, and begin script below

	var emailAddr=new GlideAjax("needitexGetEmailAddress");
	emailAddr.addParam('sysparm_name','getEmail');
	emailAddr.addParam('sysparm_userID',g_form.getValue('requested_for'));
	emailAddr.getXMLAnswer(function(answer){
		g_form.setValue('requested_for_email',answer)
	});

}
